-- Executed inside a private hci_* schema by tools/database.py init.
-- Not in the Supabase public/Data API schema. No raw data is copied to public.
CREATE TABLE settings(key TEXT PRIMARY KEY,value TEXT NOT NULL);
CREATE TABLE testers(id TEXT PRIMARY KEY,code_hash TEXT UNIQUE NOT NULL,created DOUBLE PRECISION NOT NULL,consent DOUBLE PRECISION,active_style TEXT NOT NULL CHECK(active_style IN ('reassure','guide')),suspended INTEGER NOT NULL DEFAULT 0);
CREATE TABLE conversations(id TEXT PRIMARY KEY,tester_id TEXT NOT NULL REFERENCES testers(id) ON DELETE CASCADE,style TEXT NOT NULL CHECK(style IN ('reassure','guide')),status TEXT NOT NULL CHECK(status IN ('open','completed','stopped','discarded')),started DOUBLE PRECISION NOT NULL,ended DOUBLE PRECISION,model TEXT NOT NULL,prompt_version TEXT NOT NULL,prompt_json TEXT NOT NULL,memory_refs TEXT NOT NULL);
CREATE UNIQUE INDEX one_open ON conversations(tester_id,style) WHERE status='open';
CREATE INDEX retrieval ON conversations(tester_id,style,ended DESC);
CREATE TABLE messages(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,conversation_id TEXT NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,seq INTEGER NOT NULL,role TEXT NOT NULL CHECK(role IN ('user','assistant')),text TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN ('pending','success','failed')),request_id TEXT NOT NULL,created DOUBLE PRECISION NOT NULL,model TEXT,usage TEXT NOT NULL DEFAULT '{}',flags TEXT NOT NULL DEFAULT '',UNIQUE(conversation_id,seq),UNIQUE(conversation_id,request_id,role));
CREATE TABLE memories(id TEXT PRIMARY KEY,conversation_id TEXT UNIQUE NOT NULL REFERENCES conversations(id) ON DELETE CASCADE,status TEXT NOT NULL CHECK(status IN ('pending','ready','failed','excluded')),notes TEXT,schema_version TEXT NOT NULL,model TEXT,prompt_version TEXT NOT NULL,created DOUBLE PRECISION NOT NULL,error TEXT);
CREATE TABLE events(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tester_id TEXT REFERENCES testers(id) ON DELETE CASCADE,conversation_id TEXT REFERENCES conversations(id) ON DELETE CASCADE,event TEXT NOT NULL,created DOUBLE PRECISION NOT NULL,detail TEXT NOT NULL DEFAULT '');
CREATE TABLE logins(hash TEXT PRIMARY KEY,tester_id TEXT REFERENCES testers(id) ON DELETE CASCADE,role TEXT NOT NULL,style TEXT,expires DOUBLE PRECISION NOT NULL);
CREATE TABLE api_attempts(id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,tester_hash TEXT NOT NULL,kind TEXT NOT NULL,started DOUBLE PRECISION NOT NULL,finished DOUBLE PRECISION,status TEXT NOT NULL);
CREATE INDEX api_attempt_time ON api_attempts(started);
CREATE INDEX api_attempt_tester ON api_attempts(tester_hash,started);
-- Defense in depth: no end-user Data API policies. The schema owner used by
-- the server can access its own tables; anon/authenticated are not granted access.
ALTER TABLE settings ENABLE ROW LEVEL SECURITY;
ALTER TABLE testers ENABLE ROW LEVEL SECURITY;
ALTER TABLE conversations ENABLE ROW LEVEL SECURITY;
ALTER TABLE messages ENABLE ROW LEVEL SECURITY;
ALTER TABLE memories ENABLE ROW LEVEL SECURITY;
ALTER TABLE events ENABLE ROW LEVEL SECURITY;
ALTER TABLE logins ENABLE ROW LEVEL SECURITY;
ALTER TABLE api_attempts ENABLE ROW LEVEL SECURITY;
